-- Retail (the 12.x client, which the free trial uses): the travel graph is built from the
-- game's own data, not from a hand-made map.
--   flight points, flight routes   the client's tables (data/retail_taxi.lua, generated by
--                                  tools/extract_retail.py); which flight points this
--                                  character has discovered comes live from the client
--   quest objectives and turn-ins  live from the quest log where the client shows them on
--                                  the map; otherwise the client's quest map tables
--                                  (data/retail_quests.lua)
--   quest givers                   live from the client's map (the "!" pins)
--   where you are, hearthstone,    read or measured in game (ui/retail.lua)
--   flight and mount speed
-- Planning stays on the continent you are on: stops on another continent are reported, not
-- planned, because boats, zeppelins and portals between continents are not in the tables.
--
-- Everything here is plain Lua: the game is read in ui/retail.lua, which hands over a
-- snapshot; tests build snapshots by hand.
local _, ns = ...

local Retail = {}
-- Flight paths fly at 434% of the 7 yd/s run speed (warcraft.wiki.gg, "Flight path").
-- Measured flight times replace this once the addon has timed a flight (ui/retail.lua).
Retail.TAXI_SPEED = 7 * 4.34
Retail.K = 4 -- walking edges per place to its nearest places

-- Spots in the generated tables are flat lists; `width` numbers per spot, the continent at
-- `c` (1-based within a spot). Returns the spot on `continent` nearest to (nx, ny), or nil
-- and whether the quest has spots on another continent.
local function pick(list, width, c, continent, nx, ny)
  local best, bestD, elsewhere
  for i = 1, #(list or {}), width do
    if list[i + c - 1] == continent then
      local x, y = list[i + c], list[i + c + 1]
      local d = (nx and (x - nx) ^ 2 + (y - ny) ^ 2) or 0
      if not bestD or d < bestD then best, bestD = { x = x, y = y }, d end
    else
      elsewhere = true
    end
  end
  return best, elsewhere
end
Retail.pick = pick

-- Join every walking component to its nearest neighbour component (Kruskal over straight
-- lines) so no place is cut off just because its k nearest places are all on one side.
local function connect(w)
  local World = ns.World
  local ground = {}
  for i, n in ipairs(w.nodes) do if n.kind == "ground" then ground[#ground + 1] = i end end
  local parent = {}
  local function find(i)
    while parent[i] and parent[i] ~= i do i = parent[i] end
    return i
  end
  for _, i in ipairs(ground) do parent[i] = i end
  for _, i in ipairs(ground) do
    for _, e in ipairs(w.adj[i]) do
      if e.mode == "walk" then parent[find(e.from)] = find(e.to) end
    end
  end
  local pairs_ = {}
  for a = 1, #ground do
    for b = a + 1, #ground do
      local i, j = ground[a], ground[b]
      if find(i) ~= find(j) then
        pairs_[#pairs_ + 1] = { i = i, j = j, d = World.dist(w.nodes[i], w.nodes[j]) }
      end
    end
  end
  table.sort(pairs_, function(p, q) return p.d < q.d end)
  for _, p in ipairs(pairs_) do
    local ri, rj = find(p.i), find(p.j)
    if ri ~= rj then
      parent[ri] = rj
      local d = p.d * World.WALK_DETOUR
      w:edge(p.i, p.j, "walk", d)
      w:edge(p.j, p.i, "walk", d)
    end
  end
end

-- snap = {
--   continent, x, y          where you are: instance id and world yards (UnitPosition)
--   faction, class, speed    speed = ground speed in yd/s
--   taxi   = {[nodeID] = {known, faction = "Alliance"|"Horde"|nil, name, x, y}}
--            the flight points the client shows on this continent (x, y: the client's own
--            position, used only for a node missing from the tables)
--   quests = {{id, name, complete, live = {x, y, waypoint}, liveElsewhere, done = {[i]=true}}}
--            the quest log; live = where the client's map points for it on this continent
--   givers = {{id, name, x, y}}   quests offered on the map, not accepted yet
--   hearth = {x, y, continent, name} | nil, hearthReady
--   flightSpeed (yd/s, measured), flightTimes = {["a>b"] = seconds} (measured, direct hops)
-- }
-- taxiData / questData default to ns.RetailTaxi / ns.RetailQuests.
--
-- RetailSnapshot (Adapter): a snapshot of the live client plus the game's tables as a World
-- (implements WorldSource, as ForeverMap does for the hand-built map). After build() it also
-- holds what the snapshot says about the character: profile, start, quests, notes, sources.
local RetailSnapshot = ns.Class("RetailSnapshot")
function RetailSnapshot:init(snap, taxiData, questData)
  self.snap = snap
  self.taxiData = taxiData or ns.RetailTaxi
  self.questData = questData or ns.RetailQuests
end

function RetailSnapshot:build()
  local World = ns.World
  local snap, taxiData, questData = self.snap, self.taxiData, self.questData
  local w = World.new()
  local notes, sources = {}, { live = 0, tables = 0 }
  local cont = snap.continent

  w:addPlace({ id = "here", name = "You are here", zone = "", continent = cont, x = snap.x, y = snap.y })

  -- Flight points: every one the client shows is a place (so /ar route can go there); the
  -- discovered ones of your faction (or neutral) also get a flight master.
  local known = {}
  local ids = {}
  for id in pairs(snap.taxi or {}) do ids[#ids + 1] = id end
  table.sort(ids)
  for _, id in ipairs(ids) do
    local n = snap.taxi[id]
    local t = taxiData.nodes[id]
    local x, y = n.x, n.y
    if t and t[2] == cont then x, y = t[3], t[4] end
    if x and (not n.faction or n.faction == snap.faction) then
      local name = n.name or (t and t[1]) or ("Flight point " .. id)
      w:addPlace({ id = "fp" .. id, name = name, zone = name:match(",%s*(.+)$") or "",
                   continent = cont, x = x, y = y, taxi = id })
      if n.known then
        w:addFlightMaster("fp" .. id)
        known[id] = true
      end
    end
  end
  local speed = snap.flightSpeed or Retail.TAXI_SPEED
  local times = snap.flightTimes or {}
  for _, p in ipairs(taxiData.paths) do
    local a, b, yards = p[1], p[2], p[3]
    if known[a] and known[b] then
      local ia, ib = w:index("air:fp" .. a), w:index("air:fp" .. b)
      w:edge(ia, ib, "fly", times[a .. ">" .. b] or yards / speed)
      w.flightLinks[#w.flightLinks + 1] = { a = ia, b = ib }
    end
  end

  -- Quests. Each stop is a place of its own at the game's position for it.
  local quests = {}
  local function place(id, name, pos)
    w:addPlace({ id = id, name = name, zone = "quest", continent = cont, x = pos.x, y = pos.y })
    return id
  end
  local function turnin(q, near)
    local spot, elsewhere = pick(questData.turnin[q.id], 3, 1, cont, near.x, near.y)
    if spot then
      sources.tables = sources.tables + 1
      return place("q" .. q.id .. ":turnin", q.name .. " (turn in)", spot)
    end
    notes[#notes + 1] = elsewhere and (q.name .. ": handed in on another continent, left out")
                                   or (q.name .. ": the game has no turn-in point for it, left out")
  end
  local function staticObjectives(q, near, done)
    local list, out = questData.objectives[q.id] or {}, {}
    for i = 1, #list, 4 do
      local idx = list[i]
      if not (done and done[idx]) and list[i + 1] == cont then
        sources.tables = sources.tables + 1
        out[#out + 1] = place(("q%d:o%d"):format(q.id, idx), q.name .. " (objective " .. (idx + 1) .. ")",
                              { x = list[i + 2], y = list[i + 3] })
      end
    end
    return out
  end

  for _, q in ipairs(snap.quests or {}) do
    local entry = { id = "q" .. q.id, name = q.name, accepted = true, objectives = {}, work = 0 }
    if q.complete then
      if q.live then
        sources.live = sources.live + 1
        entry.turnin = place("q" .. q.id .. ":turnin", q.name .. " (turn in)", q.live)
      else
        entry.turnin = turnin(q, snap)
      end
    else
      if q.live then
        sources.live = sources.live + 1
        entry.objectives[1] = place("q" .. q.id .. ":obj", q.name .. (q.live.waypoint and " (waypoint)" or " (objective)"), q.live)
      else
        entry.objectives = staticObjectives(q, snap, q.done)
      end
      entry.turnin = turnin(q, q.live or snap)
      if #entry.objectives == 0 and q.liveElsewhere then
        notes[#notes + 1] = q.name .. ": objective on another continent, left out"
        entry.turnin = nil
      end
    end
    if entry.turnin or #entry.objectives > 0 then quests[#quests + 1] = entry end
  end

  for _, g in ipairs(snap.givers or {}) do
    sources.live = sources.live + 1
    local entry = { id = "q" .. g.id, name = g.name, objectives = {}, work = 0,
                    giver = place("q" .. g.id .. ":giver", g.name .. " (pick up)", g) }
    entry.objectives = staticObjectives(g, g)
    entry.turnin = turnin(g, g)
    quests[#quests + 1] = entry
  end

  -- Hearthstone: only where the addon has seen it land (or bound it) on this continent.
  local profile = { faction = snap.faction, class = snap.class, speed = snap.speed or 7 }
  if snap.hearth and snap.hearth.continent == cont then
    w:addPlace({ id = "hearth", name = "Hearthstone: " .. (snap.hearth.name or "bind point"), zone = "",
                 continent = cont, x = snap.hearth.x, y = snap.hearth.y })
    if snap.hearthReady then profile.hearth = "hearth" end
  end

  w:connectWalking(Retail.K)
  connect(w)
  self.profile, self.start, self.quests, self.notes, self.sources = profile, "here", quests, notes, sources
  return w
end
ns.implements(RetailSnapshot, ns.WorldSource)

-- Returns {world, profile, start, quests, notes, sources}.
function Retail.build(snap, taxiData, questData)
  local src = RetailSnapshot.new(snap, taxiData, questData)
  local w = src:build()
  return { world = w, profile = src.profile, start = src.start, quests = src.quests,
           notes = src.notes, sources = src.sources }
end

ns.Retail, ns.RetailSnapshot = Retail, RetailSnapshot
